function getCurrentDateTime()
{
	const d = new Date();
	const day = ["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];
	const mon = ["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"];
	return day[d.getDay()]+" "+mon[d.getMonth()]+" "+d.getDate().toString().padStart(2,'0')+" "+d.getHours().toString().padStart(2,'0')+":"+d.getMinutes().toString().padStart(2,'0')+":"+d.getSeconds().toString().padStart(2,'0')+" IST "+(1900+d.getYear());
}

function xsjosGetErrorString(errorCode)
{
	switch(errorCode)
	{
		case -1001:
			return "Insufficient memory. Please try after some time.";
		case -1002:
			return "Insufficient memory. Unable to operate on the payload.";
		case -2001:
			return "Invalid certificate.";
		case -3001:
			return "Invalid calling sequence. Check if certificate is set.";
		case -4001:
			return "The specified key is unavailable.";
		default:
			return "Unknown error: "+errorCode;
	}
}

function xsjosGetString(payloadAB, key)
{
	var serialbuf = new Uint8Array(payloadAB, 0, payloadAB.byteLength);
	var serial = XSJOS._malloc(payloadAB.byteLength);
	XSJOS.HEAPU8.set(serialbuf, serial);
	
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var vallenbuf = new Uint32Array(1);
	var vallen = XSJOS._malloc(vallenbuf.length * vallenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(vallen, 0, "i32");	//NULL set
	
	var i, rv, len, ptr, str;
	
	if(key == null) rv = _xsjosGetStringObject(serial, payloadAB.byteLength, val, vallen);
	else rv = _xsjosGetString(serial, payloadAB.byteLength, key, val, vallen);
	if(rv == 0)
	{
		len = XSJOS.getValue(vallen, "i32");
		if(len > 0)
		{
			ptr = XSJOS.getValue(val, "i32");
			str = "";
			for(i=0; i<len; i++) str += String.fromCharCode(XSJOS.getValue(ptr+i, "i8"));
			//'val' is not allocated, so do not free
		}
		else
		{
			console.log("ERROR | xsjosGetString | Empty string");
			str = "";
		}
	}
	else
	{
		console.log("ERROR | xsjosGetString | "+xsjosGetErrorString(rv));
		str = null;
	}
	
	XSJOS._free(vallen);
	XSJOS._free(val);
	XSJOS._free(serial);
	return str;
}

function xsjosGetBytes(payloadAB, key)
{
	var serialbuf = new Uint8Array(payloadAB, 0, payloadAB.byteLength);
	var serial = XSJOS._malloc(payloadAB.byteLength);
	XSJOS.HEAPU8.set(serialbuf, serial);
	
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var vallenbuf = new Uint32Array(1);
	var vallen = XSJOS._malloc(vallenbuf.length * vallenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(vallen, 0, "i32");	//NULL set
	
	var i, rv, len, ptr, buf;
	
	rv = _xsjosGetBytes(serial, payloadAB.byteLength, key, val, vallen);
	if(rv == 0)
	{
		len = XSJOS.getValue(vallen, "i32");
		if(len > 0)
		{
			ptr = XSJOS.getValue(val, "i32");
			buf = new Uint8Array(len);
			for(i=0; i<len; i++) buf[i] = XSJOS.getValue(ptr+i, "i8");
			//'val' is not allocated, so do not free
		}
		else
		{
			console.log("ERROR | xsjosGetBytes | Empty buffer");
			buf = null;
		}
	}
	else
	{
		console.log("ERROR | xsjosGetBytes | "+xsjosGetErrorString(rv));
		buf = null;
	}
	
	XSJOS._free(vallen);
	XSJOS._free(val);
	XSJOS._free(serial);
	return buf;
}

function xsepfSetCertificate(certAB, pubKeyAB)
{
	var certbuf = new Uint8Array(certAB, 0, certAB.byteLength);
	var cert = XSJOS._malloc(certAB.byteLength);
	XSJOS.HEAPU8.set(certbuf, cert);
	
	var pubkeybuf = new Uint8Array(pubKeyAB, 0, pubKeyAB.byteLength);
	var pubkey = XSJOS._malloc(pubKeyAB.byteLength);
	XSJOS.HEAPU8.set(pubkeybuf, pubkey);
	
	var rv = _xsepfSetCertificate(cert, certAB.byteLength, pubkey, pubKeyAB.byteLength);
	if(rv != 0) console.log("ERROR | xsepfSetCertificate | "+xsjosGetErrorString(rv));
	
	XSJOS._free(pubkey);
	XSJOS._free(cert);
	return rv;
}

function xsepfFrameRegPayload(name, designation, mobileno)
{
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var vallenbuf = new Uint32Array(1);
	var vallen = XSJOS._malloc(vallenbuf.length * vallenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(vallen, 0, "i32");	//NULL set
	
	var i, rv, len, ptr, buf;
	
	rv = _xsepfFrameRegistrationPayload(name, designation, mobileno, val, vallen);
	if(rv == 0)
	{
		len = XSJOS.getValue(vallen, "i32");
		if(len > 0)
		{
			ptr = XSJOS.getValue(val, "i32");
			buf = new Uint8Array(len);
			for(i=0; i<len; i++) buf[i] = XSJOS.getValue(ptr+i, "i8");
			XSJOS._free(ptr);	//'val' is allocated, so free now
		}
		else
		{
			console.log("ERROR | xsepfFrameRegPayload | Empty buffer");
			buf = null;
		}
	}
	else
	{
		console.log("ERROR | xsepfFrameRegPayload | "+xsjosGetErrorString(rv));
		buf = null;
	}
	
	XSJOS._free(vallen);
	XSJOS._free(val);
	return buf;
}

