function xsepfDecryptPayload(epfKeyAB, apiKeyAB, dataAB)
{
	var k, rv, buf;
	
	var ekeybuf = new Uint8Array(epfKeyAB, 0, epfKeyAB.byteLength);
	var ekey = XSJOS._malloc(epfKeyAB.byteLength);
	XSJOS.HEAPU8.set(ekeybuf, ekey);
	
	var akeybuf = new Uint8Array(apiKeyAB, 0, apiKeyAB.byteLength);
	var akey = XSJOS._malloc(apiKeyAB.byteLength);
	XSJOS.HEAPU8.set(akeybuf, akey);
	
	var databuf = new Uint8Array(dataAB, 0, dataAB.byteLength);
	var data = XSJOS._malloc(dataAB.byteLength);
	XSJOS.HEAPU8.set(databuf, data);
	
	var outbuf = new Uint8Array(dataAB.byteLength);	//allocate output buffer to the size of input data
	var out = XSJOS._malloc(outbuf.length * outbuf.BYTES_PER_ELEMENT);
	XSJOS.HEAPU8.set(outbuf, out);
	
	buf = null;
	rv = _xsepfAESDecrypt(ekey, epfKeyAB.byteLength, akey, apiKeyAB.byteLength, data, dataAB.byteLength, out);
	if(rv <= 0) console.log("ERROR | xsepfDecryptPayload | Failed with error ", rv);
	else
	{
		//rv contains the final length of the output buffer
		buf = "";
		for(k=0; k<rv; k++) buf += String.fromCharCode(XSJOS.getValue(out+k, "i8"));
	}
	
	XSJOS._free(data);
	XSJOS._free(ekey);
	XSJOS._free(akey);
	XSJOS._free(out);
	return buf;
}

function xsepfEncryptPayload(epfKeyAB, apiKeyAB, dataAB)
{
	var k, rv, buf;
	
	var ekeybuf = new Uint8Array(epfKeyAB, 0, epfKeyAB.byteLength);
	var ekey = XSJOS._malloc(epfKeyAB.byteLength);
	XSJOS.HEAPU8.set(ekeybuf, ekey);
	
	var akeybuf = new Uint8Array(apiKeyAB, 0, apiKeyAB.byteLength);
	var akey = XSJOS._malloc(apiKeyAB.byteLength);
	XSJOS.HEAPU8.set(akeybuf, akey);
	
	var databuf = new Uint8Array(dataAB, 0, dataAB.byteLength);
	var data = XSJOS._malloc(dataAB.byteLength);
	XSJOS.HEAPU8.set(databuf, data);
	
	var outbuf = new Uint8Array(dataAB.byteLength);	//allocate output buffer to the size of input data
	var out = XSJOS._malloc(outbuf.length * outbuf.BYTES_PER_ELEMENT);
	XSJOS.HEAPU8.set(outbuf, out);
	
	buf = null;
	rv = _xsepfAESEncrypt(ekey, epfKeyAB.byteLength, akey, apiKeyAB.byteLength, data, dataAB.byteLength, out);
	if(rv <= 0) console.log("ERROR | xsepfEncryptPayload | Failed with error ", rv);
	else
	{
		//rv contains the final length of the output buffer
		buf = new Uint8Array(rv);
		for(k=0; k<rv; k++) buf[k] = XSJOS.getValue(out+k, "i8");
	}
	
	XSJOS._free(data);
	XSJOS._free(ekey);
	XSJOS._free(akey);
	XSJOS._free(out);
	return buf;
}

