//frame the signed, encrypted and compressed payload for "Bid Submission"
function xscpppFrameSignature(docAB, sigAB, keyAB)
{
	var i, rv, ptr, buf, sdig, esdig, ocrc, oulen;
	
	var docbuf = new Uint8Array(docAB, 0, docAB.byteLength);
	var doc = XSJOS._malloc(docAB.byteLength);
	XSJOS.HEAPU8.set(docbuf, doc);
	
	var sigbuf = new Uint8Array(sigAB, 0, sigAB.byteLength);
	var sig = XSJOS._malloc(sigAB.byteLength);
	XSJOS.HEAPU8.set(sigbuf, sig);
	
	var keybuf = new Uint8Array(keyAB, 0, keyAB.byteLength);
	var key = XSJOS._malloc(keyAB.byteLength);
	XSJOS.HEAPU8.set(keybuf, key);
	
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var sigdigestbuf = new Uint8Array(20);
	var sigdigest = XSJOS._malloc(sigdigestbuf.length * sigdigestbuf.BYTES_PER_ELEMENT);
	XSJOS.HEAPU8.set(sigdigestbuf, sigdigest);
	
	var encsigdigestbuf = new Uint8Array(20);
	var encsigdigest = XSJOS._malloc(encsigdigestbuf.length * encsigdigestbuf.BYTES_PER_ELEMENT);
	XSJOS.HEAPU8.set(encsigdigestbuf, encsigdigest);
	
	var crcbuf = new Uint32Array(1);
	var crc = XSJOS._malloc(crcbuf.length * crcbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(crc, 0, "i32");	//NULL set
	
	var ulenbuf = new Uint32Array(1);
	var ulen = XSJOS._malloc(ulenbuf.length * ulenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(ulen, 0, "i32");	//NULL set
	
	rv = _xscpppFrameSignature(doc, docAB.byteLength, sig, sigAB.byteLength, key, val, sigdigest, encsigdigest, crc, ulen);
	if(rv > 0)
	{
		ptr = XSJOS.getValue(val, "i32");
		buf = new Uint8Array(rv);
		for(i=0; i<rv; i++) buf[i] = XSJOS.getValue(ptr+i, "i8");
		XSJOS._free(ptr);	//pointer to 'val' is allocated, so free now
		
		sdig = new Uint8Array(20);
		for(i=0; i<20; i++) sdig[i] = XSJOS.getValue(sigdigest+i, "i8");
		
		esdig = new Uint8Array(20);
		for(i=0; i<20; i++) esdig[i] = XSJOS.getValue(encsigdigest+i, "i8");
		
		ocrc = XSJOS.getValue(crc, "i32");
		oulen = XSJOS.getValue(ulen, "i32");
	}
	else
	{
		console.log("ERROR | xscpppFrameSignature | "+xsjosGetErrorString(rv));
		buf = null;
		sdig = null;
		esdig = null;
		ocrc = 0;
		oulen = 0;
	}
	
	XSJOS._free(ulen);
	XSJOS._free(crc);
	XSJOS._free(encsigdigest);
	XSJOS._free(sigdigest);
	XSJOS._free(val);
	XSJOS._free(key);
	XSJOS._free(sig);
	XSJOS._free(doc);
	return [buf, sdig, esdig, ocrc, oulen];
}

