//functions to frame the "Bid Submission" payload
function _xsutilRSAPublicEncrypt(pubKeyAB, dataAB)
{
	const RANDOMBYTE = 184;
	var k, rv, rsa, buf, len;
	var jspad = new Uint8Array(256);	//pad can be atmost 256 bytes for RSA-2048 bit key
	
	try {
		crypto.getRandomValues(jspad);
		//convert ZERO in random pad bytes to 184 (ie. just something other than ZERO)
		//as pad bytes cannot be ZERO and will result in decryption error
		for(k=0; k<256; k++)
		{
			if(jspad[k] == 0) jspad[k] = RANDOMBYTE;
		}
	} catch(e) {
		console.log("WARNING: Random pad byte generation failed. Fallback applied.");
		jspad[0] = RANDOMBYTE;
		for(k=1; k<256; k++) jspad[k] = k;
	}
	
	var padbuf = new Uint8Array(jspad, 0, jspad.byteLength);
	var pad = XSJOS._malloc(jspad.byteLength);
	XSJOS.HEAPU8.set(padbuf, pad);
	
	var keybuf = new Uint8Array(pubKeyAB, 0, pubKeyAB.byteLength);
	var key = XSJOS._malloc(pubKeyAB.byteLength);
	XSJOS.HEAPU8.set(keybuf, key);
	
	var databuf = new Uint8Array(dataAB, 0, dataAB.byteLength);
	var data = XSJOS._malloc(dataAB.byteLength);
	XSJOS.HEAPU8.set(databuf, data);
	
	var valbuf = new Uint8Array(256);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var vallenbuf = new Uint32Array(1);
	var vallen = XSJOS._malloc(vallenbuf.length * vallenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(vallen, valbuf.length * valbuf.BYTES_PER_ELEMENT, "i32");	//initialize to the size of the allocated output buffer
	
	buf = null;
	rsa = _CM_p1GetParams(key, pubKeyAB.byteLength, 0);
	if(rsa == null) console.log("ERROR | _xscpppRSAPublicEncrypt | Improper public key | ", pubKeyAB);
	else
	{
		rv = _RSA_PublicEncrypt(data, dataAB.byteLength, rsa, 8, null, 0, val, vallen, pad, jspad.byteLength);	//2 for PKCS1 padding with random pad bytes
		if(rv != 0) console.log("ERROR | _xscpppRSAPublicEncrypt | RSA public encrypt failed | ", rv, pubKeyAB, dataAB);
		else
		{
			len = XSJOS.getValue(vallen, "i32");
			if(len > 0)
			{
				buf = new Uint8Array(len);
				for(k=0; k<len; k++) buf[k] = XSJOS.getValue(val+k, "i8");
			}
			else console.log("ERROR | _xscpppRSAPublicEncrypt | Encrypted public key is empty");
		}
		
		_CM_p1DeleteRSA(rsa);
	}
	
	XSJOS._free(pad);
	XSJOS._free(key);
	XSJOS._free(data);
	XSJOS._free(vallen);
	XSJOS._free(val);
	return buf;
}

function xsGetBigInt(bignum)
{
	var valbuf = new Uint8Array(8);
	
	var jview = new DataView(valbuf.buffer);
	jview.setBigUint64(0, bignum, false);	//false to convert to BigEndian for Java APPLET class serialization
	
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.HEAPU8.set(valbuf, val);
	
	return val;	//"val" is allocated; should be released by the caller
}

function xscpppBidInit(aparams, testkey)
{
	const KEYSIZE = 16;	//in bytes
	var enckey = new Uint8Array(KEYSIZE);
	var i, j, rv, pubkey, keyindex, checkpriority;
	var buf, splitlen, splitkey, keypriority;
	var bidId, workItemId, packetId, boTypeId, bidOpenerId, jsBoTypeId;
	var ctx = {
		key: null,
		bidFactor: null,
		bidDoc: null,
		bidOpener: null,
		bidGeneric: null,
		bidPacket: null
	};
	
	if(aparams == null || aparams.generic_applet == undefined || aparams.generic_applet.length != 1 || aparams.packet_applet == undefined || aparams.packet_applet.length != 1 || aparams.openerkey_applet == undefined || aparams.openerkey_applet.length <= 0)
	{
		console.log("ERROR | xscpppBidInit | Invalid APPLET params");
		console.log(aparams);
		return null;
	}
	
	//generate an 128-bit random to be used as key for AES-ECB
	try {
		if(testkey == undefined) crypto.getRandomValues(enckey);
		else enckey = testkey.slice(0);
		ctx.key = enckey;
		//console.log(B64.encode(enckey));
	} catch(e) {
		console.log("ERROR | xscpppBidInit | Key generation failed");
		console.log(e);
		//TODO: consider using Math.random during failures
		return null;
	}
	
	//load the packet_applet params
	packetId = xsGetBigInt(aparams.packet_applet[0].packetId);
	
	ctx.bidPacket = _xscpppAddBidPacket(packetId, aparams.packet_applet[0].packetName, aparams.packet_applet[0].packetRefNo);
	
	XSJOS._free(packetId);
	if(ctx.bidPacket == null)
	{
		console.log("ERROR | xscpppBidInit | Failed to add BidPacket");
		_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
		ctx = undefined;
		return null;
	}
	
	//load the generic_applet params
	bidId = xsGetBigInt(aparams.generic_applet[0].bidId);
	workItemId = xsGetBigInt(aparams.generic_applet[0].workItemId);
	boTypeId = xsGetBigInt(aparams.generic_applet[0].boTypeId);
	jsBoTypeId = aparams.generic_applet[0].boTypeId;	//already a BigInt
	
	ctx.bidGeneric = _xscpppAddBidGeneric(bidId, workItemId, aparams.generic_applet[0].thumbPrint, aparams.generic_applet[0].serverTime, aparams.generic_applet[0].portUrl, aparams.generic_applet[0].defaultFolder, boTypeId, aparams.generic_applet[0].reBid, aparams.generic_applet[0].validateBoqVersion, aparams.generic_applet[0].fileHash);
	
	XSJOS._free(bidId);
	XSJOS._free(workItemId);
	if(ctx.bidGeneric == null)
	{
		console.log("ERROR | xscpppBidInit | Failed to add BidGeneric");
		_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
		ctx = undefined;
		XSJOS._free(boTypeId);
		return null;
	}
	
	//load the openerkey_applet params
	bidOpenerId = [];
	for(i=0; i<aparams.openerkey_applet.length; i++)
	{
		bidOpenerId.push(xsGetBigInt(aparams.openerkey_applet[i].id));
		rv = _xscpppAddBidOpener(bidOpenerId[i], aparams.openerkey_applet[i].bidOpenerPublicKey, (aparams.openerkey_applet[i].keyPriority==undefined)?null:(aparams.openerkey_applet[i].keyPriority), ctx.bidOpener);	//MAK: NULL checking for keyPriority
		if(rv == null)
		{
			console.log("ERROR | xscpppBidInit | Failed to add BidOpener | ", i);
			_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
			ctx = undefined;
			XSJOS._free(boTypeId);
			for(i=0; i<bidOpenerId.length; i++) XSJOS._free(bidOpenerId[i]);
			return null;
		}
		if(ctx.bidOpener==null) ctx.bidOpener = rv;	//preserve the first context to feed later
	}
	
	
	if(jsBoTypeId != 5n)
	{
		if(jsBoTypeId == 3n || jsBoTypeId == 4n) checkpriority = true;
		else checkpriority = false;
		
		//split the key based on the "boTypeId"
		splitlen = Math.floor(KEYSIZE/aparams.openerkey_applet.length);
		i  = keyindex = 0;
		//console.log("Start | ", splitlen, aparams.openerkey_applet.length);
		
		do {
			
			//MAK: just follow their algorithm
			if(jsBoTypeId != 4n && keyindex == 2) splitkey = enckey.slice(i, i+(KEYSIZE-(splitlen*2)));
			else splitkey = enckey.slice(i, i+splitlen);
			//console.log("Do | ", i, keyindex);
			//console.log(splitkey);
			
			keypriority = null;
			//encrypt the split key with multiple bid openers as specified in "keyPriority"
			for(j=0; j<aparams.openerkey_applet.length; j++)
			{
				//console.log("For | ", j, checkpriority, aparams.openerkey_applet[j].keyPriority, keyindex);
				if(checkpriority == false)
				{
					if(j != keyindex) continue;
					else keypriority = keyindex.toString();
				}
				else if(aparams.openerkey_applet[j].keyPriority != undefined) keypriority = aparams.openerkey_applet[j].keyPriority;
				//else when the keyPriority is not defined, use the current keyPriority (saved in the previous loop)
				
				if(checkpriority == true && keypriority == null)
				{
					//this case results in the APPLET crash; we validate and return error to avoid submission
					console.log("ERROR | xscpppBidInit | keyPriority is empty | ", keyindex);
					_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
					ctx = undefined;
					XSJOS._free(boTypeId);
					for(i=0; i<bidOpenerId.length; i++) XSJOS._free(bidOpenerId[i]);
					return null;
				}
				
				//for certain cases we need not check the priority
				//in those cases just encrypt each split key with all bid openers' public key
				if(keypriority.indexOf(keyindex.toString()) != -1)
				{
					pubkey = XSCUTILS._base64ToArrayBuffer(aparams.openerkey_applet[j].bidOpenerPublicKey);
					buf = _xsutilRSAPublicEncrypt(pubkey, splitkey);
					//console.log("Encrypt key", buf);
					
					if(buf != null)
					{
						rv = _xscpppAddBidFactor(bidOpenerId[j], B64.encode(buf), (checkpriority==false)?null:keyindex.toString(), ctx.bidFactor);	//MAK: NULL setting keyPriority when not required
						if(rv == null)
						{
							console.log("ERROR | xscpppBidInit | Failed to add BidFactor | ", keyindex, buf);
							_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
							ctx = undefined;
							XSJOS._free(boTypeId);
							for(i=0; i<bidOpenerId.length; i++) XSJOS._free(bidOpenerId[i]);
							return null;
						}
						
						if(ctx.bidFactor==null) ctx.bidFactor = rv;	//preserve the first context to feed later
						buf = null;
					}
					else
					{
						console.log("ERROR | xscpppBidInit | Encrypted public key is empty | ", keyindex);
						_xscpppClearBidCtx(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, null, ctx.bidFactor);
						ctx = undefined;
						XSJOS._free(boTypeId);
						for(i=0; i<bidOpenerId.length; i++) XSJOS._free(bidOpenerId[i]);
						return null;
					}
				}
			}
			
			i += splitlen;
			keyindex++;
		} while(keyindex < aparams.openerkey_applet.length);
	}
	//else when jsBoTypeId is "5" do not split key but create an empty "BidFactorAppletInput" class
	
	XSJOS._free(boTypeId);
	for(i=0; i<bidOpenerId.length; i++) XSJOS._free(bidOpenerId[i]);
	return ctx;
}

function xscpppBidFinalize(ctx)
{
	var ocrc, oulen;
	
	var crcbuf = new Uint32Array(1);
	var crc = XSJOS._malloc(crcbuf.length * crcbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(crc, 0, "i32");	//NULL set
	
	var ulenbuf = new Uint32Array(1);
	var ulen = XSJOS._malloc(ulenbuf.length * ulenbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(ulen, 0, "i32");	//NULL set
	
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	var len = _xscpppFrameBidMeta(ctx.bidPacket, ctx.bidOpener, ctx.bidGeneric, ctx.bidDoc, ctx.bidFactor, val, crc, ulen);
	if(len <= 0)
	{
		console.log("ERROR | xscpppBidFinalize | Failed to create bid meta file | ", len);
		return [null, 0, 0];
	}
	
	var ptr = XSJOS.getValue(val, "i32");
	var buf = new Uint8Array(len);
	for(var i=0; i<len; i++) buf[i] = XSJOS.getValue(ptr+i, "i8");
	XSJOS._free(ptr);	//pointer to 'val' is allocated, so free now
	
	ocrc = XSJOS.getValue(crc, "i32");
	oulen = XSJOS.getValue(ulen, "i32");
	
	XSJOS._free(crc);
	XSJOS._free(ulen);
	XSJOS._free(val);
	
	//INFO: add "buf" to JAR in the caller
	return [buf, ocrc, oulen];
}

function xscpppAddBidDoc(docctx, adocparam, filename, txtfilename, docAB, sigAB, keyAB)
{
	var ctx, sdo, signature, sigdig, encsigdig, filetype, docdigest;
	var rv, txtfilenamedigest, crc1, crc2, ulen1, ulen2, id, filesize;
	
	if((rv = filename.lastIndexOf(".")) != -1) filetype = filename.substring(rv+1);
	else filetype = "";
	
	[rv, txtfilenamedigest] = xsSHA1(XSCUTILS.str2ab(txtfilename));
	if(rv != 0)
	{
		console.log("ERROR | xscpppAddBidDoc | Failed to compute file name digest");
		return null;
	}
	
	[rv, docdigest] = xsSHA1(docAB);
	if(rv != 0)
	{
		console.log("ERROR | xscpppAddBidDoc | Failed to compute document digest");
		return null;
	}
	
	[signature, sigdig, encsigdig, crc1, ulen1] = xscpppFrameSignature(docAB, sigAB, keyAB);
	if(signature == null)
	{
		console.log("ERROR | xscpppAddBidDoc | Failed to frame signature payload");
		return null;
	}
	
	[sdo, crc2, ulen2] = xscpppFrameBidSDO(filetype, filename, B64.encode(txtfilenamedigest), B64.encode(docdigest), B64.encode(sigdig), B64.encode(encsigdig));
	if(sdo == null)
	{
		console.log("ERROR | xscpppAddBidDoc | Failed to frame SecureDataObject");
		return null;
	}
	
	id = xsGetBigInt(adocparam.id);
	filesize = xsGetBigInt(BigInt(Math.floor(docAB.byteLength/1024)));	//will be within the javascript "Number" range only
	rv = _xscpppAddBidDoc(id, filename, adocparam.description, adocparam.type, adocparam.sNo, filesize, adocparam.isBoqFile, docctx);
	XSJOS._free(id);
	XSJOS._free(filesize);
	if(rv == null)
	{
		console.log("ERROR | xscpppAddBidDoc | Failed to add document context");
		return null;
	}
	
	//INFO: add "signature" and "sdo" to JAR in the caller
	return [rv, signature, crc1, ulen1, sdo, crc2, ulen2];
}

//get a compressed data and datalen for packing JAR
function xscpppGetCompressed(docAB)
{
	var i, rv, ptr, buf, ocrc;
	
	var docbuf = new Uint8Array(docAB, 0, docAB.byteLength);
	var doc = XSJOS._malloc(docAB.byteLength);
	XSJOS.HEAPU8.set(docbuf, doc);
	
	var valbuf = new Uint32Array(1);
	var val = XSJOS._malloc(valbuf.length * valbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(val, 0, "i32");	//NULL set
	
	var crcbuf = new Uint32Array(1);
	var crc = XSJOS._malloc(crcbuf.length * crcbuf.BYTES_PER_ELEMENT);
	XSJOS.setValue(crc, 0, "i32");	//NULL set
	
	rv = _xscpppGetCompressed(doc, docAB.byteLength, crc, val);
	if(rv > 0)
	{
		ptr = XSJOS.getValue(val, "i32");
		buf = new Uint8Array(rv);
		for(i=0; i<rv; i++) buf[i] = XSJOS.getValue(ptr+i, "i8");
		XSJOS._free(ptr);	//pointer to 'val' is allocated, so free now
		
		ocrc = XSJOS.getValue(crc, "i32");
	}
	else
	{
		console.log("ERROR | xscpppGetCompressed | "+rv);
		buf = null;
		ocrc = 0;
	}
	
	XSJOS._free(crc);
	XSJOS._free(doc);
	XSJOS._free(val);
	return [buf, rv, ocrc];
}